import React, { useState, useMemo, useCallback } from "react"
import {
  startOfMonth,
  endOfMonth,
  startOfWeek,
  endOfWeek,
  subMonths,
  format,
} from "date-fns"
import { getDocs, doc, getDoc } from "firebase/firestore"
import { db } from "../../../firebase/config"
import { useServiceReports } from "../../../hooks/useServiceReports"
import { ServiceTicket } from "../../../hooks/useServiceTickets"
import { Client } from "../../../hooks/useClients"
import ServiceTicketDetail from "./ServiceTicketDetail"

const PAGE_SIZE = 20

function fmt(n: number) {
  return `$ ${n.toLocaleString("en-CA", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
}

function toInputDate(d: Date) {
  return format(d, "yyyy-MM-dd")
}

type SortDir = "asc" | "desc"

const STATUS_ROW: Record<string, string> = {
  completed: "bg-green-50",
  cancelled: "opacity-50",
}

export default function ServiceReportsList() {
  const today = new Date()
  const [fromDate, setFromDate] = useState(toInputDate(startOfMonth(today)))
  const [toDate, setToDate] = useState(toInputDate(endOfMonth(today)))
  const [appliedFrom, setAppliedFrom] = useState(startOfMonth(today))
  const [appliedTo, setAppliedTo] = useState(endOfMonth(today))
  const [sortDir, setSortDir] = useState<SortDir>("asc")
  const [page, setPage] = useState(0)
  const [selectedTicket, setSelectedTicket] = useState<ServiceTicket | null>(null)
  const [selectedClient, setSelectedClient] = useState<Client | null>(null)
  const [clientCache, setClientCache] = useState<Record<string, Client>>({})

  const { tickets, loading, error, totals } = useServiceReports(appliedFrom, appliedTo)

  function apply() {
    setAppliedFrom(new Date(fromDate))
    setAppliedTo(new Date(toDate))
    setPage(0)
  }

  function reset() {
    const s = startOfMonth(today)
    const e = endOfMonth(today)
    setFromDate(toInputDate(s))
    setToDate(toInputDate(e))
    setAppliedFrom(s)
    setAppliedTo(e)
    setPage(0)
  }

  function setQuickFilter(s: Date, e: Date) {
    setFromDate(toInputDate(s))
    setToDate(toInputDate(e))
    setAppliedFrom(s)
    setAppliedTo(e)
    setPage(0)
  }

  const sorted = useMemo(() => {
    return [...tickets].sort((a, b) => {
      const diff = a.createdAt.getTime() - b.createdAt.getTime()
      return sortDir === "asc" ? diff : -diff
    })
  }, [tickets, sortDir])

  const paged = sorted.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE)
  const totalPages = Math.ceil(sorted.length / PAGE_SIZE)
  const showingFrom = sorted.length === 0 ? 0 : page * PAGE_SIZE + 1
  const showingTo = Math.min((page + 1) * PAGE_SIZE, sorted.length)

  async function openDetail(ticket: ServiceTicket) {
    setSelectedTicket(ticket)
    if (clientCache[ticket.clientId]) {
      setSelectedClient(clientCache[ticket.clientId])
      return
    }
    if (!db) return
    const snap = await getDoc(doc(db, "clients", ticket.clientId))
    if (snap.exists()) {
      const data = snap.data()
      const client: Client = {
        id: snap.id,
        name: data.name,
        phone: data.phone,
        email: data.email ?? "",
        address: data.address ?? "",
        vehicles: data.vehicles ?? [],
        portalTokens: data.portalTokens ?? [],
        createdAt: data.createdAt.toDate(),
        updatedAt: data.updatedAt.toDate(),
      }
      setClientCache(c => ({ ...c, [client.id]: client }))
      setSelectedClient(client)
    } else {
      setSelectedClient(null)
    }
  }

  function exportCSV() {
    const headers = ["Date", "Client", "Vehicle", "Service", "Billable", "GST", "QST", "Non-Billable", "Status"]
    const rows = sorted.map(t => {
      const client = clientCache[t.clientId]
      const vehicle = client?.vehicles.find(v => v.vehicleId === t.vehicleId)
      const vehicleStr = vehicle ? `${vehicle.year} ${vehicle.make} ${vehicle.model}` : t.vehicleId
      return [
        format(t.createdAt, "yyyy-MM-dd"),
        t.clientName,
        vehicleStr,
        t.serviceTypes.join(", "),
        t.billableAmount.toFixed(2),
        t.taxGST.toFixed(2),
        t.taxQST.toFixed(2),
        t.nonBillableAmount.toFixed(2),
        t.status,
      ]
    })

    const csv = [headers, ...rows]
      .map(r => r.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(","))
      .join("\n")

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" })
    const url = URL.createObjectURL(blob)
    const a = document.createElement("a")
    a.href = url
    a.download = `service-report-${toInputDate(appliedFrom)}_to_${toInputDate(appliedTo)}.csv`
    a.click()
    URL.revokeObjectURL(url)
  }

  return (
    <div className="flex flex-col gap-4">
      {/* Filters */}
      <div className="bg-white rounded-xl shadow-sm p-4">
        <div className="flex flex-wrap items-end gap-3">
          <div>
            <label className="block text-xs font-medium text-gray-600 mb-1">From</label>
            <input
              type="date"
              value={fromDate}
              onChange={e => setFromDate(e.target.value)}
              className="border border-gray-300 rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-600 mb-1">To</label>
            <input
              type="date"
              value={toDate}
              onChange={e => setToDate(e.target.value)}
              className="border border-gray-300 rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <button
            onClick={apply}
            className="px-4 py-1.5 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors"
          >
            Apply
          </button>
          <button
            onClick={reset}
            className="px-4 py-1.5 border border-gray-300 text-gray-600 text-sm rounded-lg hover:bg-gray-50 transition-colors"
          >
            Reset
          </button>

          {/* Quick filters */}
          <div className="flex gap-2 ml-auto">
            {[
              {
                label: "This Week",
                s: startOfWeek(today, { weekStartsOn: 1 }),
                e: endOfWeek(today, { weekStartsOn: 1 }),
              },
              { label: "This Month", s: startOfMonth(today), e: endOfMonth(today) },
              {
                label: "Last Month",
                s: startOfMonth(subMonths(today, 1)),
                e: endOfMonth(subMonths(today, 1)),
              },
            ].map(({ label, s, e }) => (
              <button
                key={label}
                onClick={() => setQuickFilter(s, e)}
                className="px-3 py-1.5 text-xs border border-gray-200 rounded-lg hover:bg-gray-100 text-gray-600 transition-colors"
              >
                {label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm overflow-hidden">
        {/* Table header actions */}
        <div className="flex items-center justify-between px-4 py-3 border-b border-gray-100">
          <p className="text-xs text-gray-500">
            {loading
              ? "Loading…"
              : `Showing ${showingFrom}–${showingTo} of ${sorted.length} records`}
          </p>
          <button
            onClick={exportCSV}
            disabled={sorted.length === 0}
            className="text-xs px-3 py-1.5 border border-gray-200 rounded-lg hover:bg-gray-50 text-gray-600 disabled:opacity-40 transition-colors"
          >
            Export CSV
          </button>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-16">
            <div className="w-6 h-6 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
          </div>
        ) : error ? (
          <div className="px-4 py-8 text-center text-sm text-red-500">{error}</div>
        ) : sorted.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-gray-400 gap-2">
            <span className="text-4xl">📋</span>
            <p className="text-sm">No service records found for this period.</p>
          </div>
        ) : (
          <>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left border-b border-gray-100">
                    <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide">#</th>
                    <th
                      className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide cursor-pointer select-none hover:text-gray-700"
                      onClick={() => { setSortDir(d => d === "asc" ? "desc" : "asc"); setPage(0) }}
                    >
                      Date {sortDir === "asc" ? "↑" : "↓"}
                    </th>
                    <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide">Client</th>
                    <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide">Service</th>
                    <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide text-right">Billable</th>
                    <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide text-right">Non-Billable</th>
                    <th className="px-4 py-3 text-xs font-semibold text-gray-500 uppercase tracking-wide">Status</th>
                  </tr>
                </thead>
                <tbody>
                  {paged.map((ticket, i) => {
                    const rowClass = STATUS_ROW[ticket.status] ?? ""
                    const cancelled = ticket.status === "cancelled"
                    return (
                      <tr
                        key={ticket.id}
                        onClick={() => openDetail(ticket)}
                        className={`border-b border-gray-50 cursor-pointer hover:bg-blue-50 transition-colors ${rowClass}`}
                      >
                        <td className="px-4 py-3 text-gray-400 text-xs">{page * PAGE_SIZE + i + 1}</td>
                        <td className={`px-4 py-3 text-gray-700 ${cancelled ? "line-through" : ""}`}>
                          {format(ticket.createdAt, "MMM d, yyyy")}
                        </td>
                        <td className={`px-4 py-3 font-medium text-gray-800 ${cancelled ? "line-through" : ""}`}>
                          {ticket.clientName}
                        </td>
                        <td className={`px-4 py-3 text-gray-600 capitalize ${cancelled ? "line-through" : ""}`}>
                          {ticket.serviceTypes.map(s => s === "custom" ? "Custom" : s.replace(/-/g, " ")).join(", ")}
                        </td>
                        <td className="px-4 py-3 text-right text-gray-700 font-mono">
                          {ticket.billableAmount > 0 ? fmt(ticket.billableAmount) : "—"}
                        </td>
                        <td className="px-4 py-3 text-right text-gray-700 font-mono">
                          {ticket.nonBillableAmount > 0 ? fmt(ticket.nonBillableAmount) : "—"}
                        </td>
                        <td className="px-4 py-3">
                          <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${
                            ticket.status === "completed"
                              ? "bg-green-100 text-green-700"
                              : ticket.status === "cancelled"
                              ? "bg-red-100 text-red-500"
                              : "bg-gray-100 text-gray-600"
                          }`}>
                            {ticket.status}
                          </span>
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>

            {/* Totals footer */}
            <div className="border-t border-gray-200 px-4 py-4 bg-gray-50">
              <div className="flex flex-wrap gap-x-8 gap-y-1 text-sm font-mono justify-end">
                <span className="text-gray-600">
                  Billable Subtotal: <span className="font-semibold text-gray-800">{fmt(totals.billableSubtotal)}</span>
                </span>
                <span className="text-gray-600">
                  GST collected: <span className="font-semibold text-gray-800">{fmt(totals.totalGST)}</span>
                </span>
                <span className="text-gray-600">
                  QST collected: <span className="font-semibold text-gray-800">{fmt(totals.totalQST)}</span>
                </span>
                <span className="text-gray-600">
                  Non-Billable: <span className="font-semibold text-gray-800">{fmt(totals.totalNonBillable)}</span>
                </span>
                <span className="text-gray-800 font-bold border-l border-gray-300 pl-8">
                  Grand Total: {fmt(totals.grandTotal)}
                </span>
              </div>
            </div>

            {/* Pagination */}
            {totalPages > 1 && (
              <div className="flex items-center justify-between px-4 py-3 border-t border-gray-100">
                <button
                  onClick={() => setPage(p => Math.max(0, p - 1))}
                  disabled={page === 0}
                  className="text-sm px-3 py-1.5 border border-gray-200 rounded-lg disabled:opacity-40 hover:bg-gray-50 transition-colors"
                >
                  ← Previous
                </button>
                <span className="text-xs text-gray-500">
                  Page {page + 1} of {totalPages}
                </span>
                <button
                  onClick={() => setPage(p => Math.min(totalPages - 1, p + 1))}
                  disabled={page === totalPages - 1}
                  className="text-sm px-3 py-1.5 border border-gray-200 rounded-lg disabled:opacity-40 hover:bg-gray-50 transition-colors"
                >
                  Next →
                </button>
              </div>
            )}
          </>
        )}
      </div>

      {/* Detail modal */}
      {selectedTicket && (
        <ServiceTicketDetail
          ticket={selectedTicket}
          client={selectedClient}
          onClose={() => { setSelectedTicket(null); setSelectedClient(null) }}
        />
      )}
    </div>
  )
}
