import React from "react"
import { graphql } from "gatsby"
import { useRequireAuth } from "../../../hooks/useRequireAuth"
import AdminLayout from "../../../components/admin/AdminLayout"
import ServiceReportsList from "../../../components/admin/Reports/ServiceReportsList"

export default function ServiceReportsPage() {
  const { currentUser, loading } = useRequireAuth()

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (!currentUser) return null

  return (
    <AdminLayout currentPath="/admin/reports/services">
      <div className="mb-6">
        <h1 className="text-xl font-bold text-gray-800">Service Reports</h1>
        <p className="text-sm text-gray-500 mt-0.5">Filter by date range to view service records and totals.</p>
      </div>
      <ServiceReportsList />
    </AdminLayout>
  )
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`
