// Firestore index required for this query:
// Collection: serviceTickets
// Fields: createdAt ASC, status ASC (composite)
// Create at: Firebase Console → Firestore → Indexes → Add Index

import { useState, useEffect } from "react"
import {
  collection,
  query,
  where,
  getDocs,
  Timestamp,
  orderBy,
} from "firebase/firestore"
import { db } from "../firebase/config"
import { ServiceTicket } from "./useServiceTickets"

export interface ServiceReportTotals {
  billableSubtotal: number
  totalGST: number
  totalQST: number
  totalNonBillable: number
  grandTotal: number
}

interface UseServiceReportsResult {
  tickets: ServiceTicket[]
  loading: boolean
  error: string | null
  totals: ServiceReportTotals
}

const ZERO_TOTALS: ServiceReportTotals = {
  billableSubtotal: 0,
  totalGST: 0,
  totalQST: 0,
  totalNonBillable: 0,
  grandTotal: 0,
}

function calcTotals(tickets: ServiceTicket[]): ServiceReportTotals {
  return tickets.reduce<ServiceReportTotals>(
    (acc, t) => ({
      billableSubtotal: acc.billableSubtotal + t.billableAmount,
      totalGST: acc.totalGST + t.taxGST,
      totalQST: acc.totalQST + t.taxQST,
      totalNonBillable: acc.totalNonBillable + t.nonBillableAmount,
      grandTotal:
        acc.grandTotal +
        t.billableAmount +
        t.taxGST +
        t.taxQST +
        t.nonBillableAmount,
    }),
    { ...ZERO_TOTALS }
  )
}

export function useServiceReports(
  startDate: Date,
  endDate: Date
): UseServiceReportsResult {
  const [tickets, setTickets] = useState<ServiceTicket[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (!db) {
      setLoading(false)
      return
    }

    setLoading(true)
    setError(null)

    // Extend endDate to end of day
    const end = new Date(endDate)
    end.setHours(23, 59, 59, 999)

    getDocs(
      query(
        collection(db, "serviceTickets"),
        where("createdAt", ">=", Timestamp.fromDate(startDate)),
        where("createdAt", "<=", Timestamp.fromDate(end)),
        orderBy("createdAt", "asc")
      )
    )
      .then(snap => {
        const data: ServiceTicket[] = snap.docs.map(d => {
          const raw = d.data()
          return {
            id: d.id,
            appointmentId: raw.appointmentId,
            clientId: raw.clientId,
            clientName: raw.clientName,
            vehicleId: raw.vehicleId,
            serviceTypes: Array.isArray(raw.serviceTypes) ? raw.serviceTypes : raw.serviceType ? [raw.serviceType] : [],
            customServiceDescription: raw.customServiceDescription ?? "",
            quotedPrice: raw.quotedPrice ?? 0,
            estimatedDuration: raw.estimatedDuration ?? 0,
            billableAmount: raw.billableAmount ?? 0,
            taxGST: raw.taxGST ?? 0,
            taxQST: raw.taxQST ?? 0,
            nonBillableAmount: raw.nonBillableAmount ?? 0,
            sendConfirmation: raw.sendConfirmation ?? false,
            status: raw.status,
            createdAt: (raw.createdAt as Timestamp).toDate(),
            updatedAt: (raw.updatedAt as Timestamp).toDate(),
          }
        })
        setTickets(data)
      })
      .catch(err => setError(err.message))
      .finally(() => setLoading(false))
  }, [startDate.toISOString(), endDate.toISOString()])

  return { tickets, loading, error, totals: calcTotals(tickets) }
}
